def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract recent history for analysis
    window = min(20, n)
    recent = history[-window:]

    # Calculate cooperation rates
    opp_coops_recent = sum(1 for _, o in recent if o == 'C')
    rate_recent = opp_coops_recent / window

    total_opp_coops = sum(1 for _, o in history if o == 'C')
    rate_total = total_opp_coops / n

    last_me, last_opp = history[-1]

    # Streak detection
    streak_defects = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_defects += 1
        else:
            break

    streak_coops = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_coops += 1
        else:
            break

    # Strategy Logic

    # 1. If opponent is highly cooperative (Recent > 75% AND Total > 60%)
    if rate_recent >= 0.75 and rate_total >= 0.6:
        # If they just defected after a long coop streak, forgive once to avoid noise traps
        if last_opp == 'D' and streak_coops >= 3:
             # Check if this is an isolated defect (previous was C)
             if n >= 2 and history[-2][1] == 'C':
                 return 'C'
             else:
                 return 'D'

        # If they are consistently cooperating, reciprocate
        if last_opp == 'C':
            return 'C'

        # If they defected but we were already in retaliation or mixed state
        if last_opp == 'D':
            return 'D'

    # 2. If opponent is mostly defecting (Total < 40%)
    if rate_total < 0.4:
        # Always defend against persistent defectors
        if last_opp == 'C':
            # Occasional probe if they suddenly cooperated, but usually stick to D to punish past behavior
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        else:
            return 'D'

    # 3. Mixed/Uncertain Behavior
    # Default to Tit-for-Tat with slight forgiveness/probing

    if last_opp == 'D':
        # Retaliate
        # But if it's the very first defect after a long cooperation streak, maybe forgive with some probability
        if streak_coops >= 5 and rng.random() < 0.2:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated last turn
        # Reciprocate cooperation generally
        # But if overall trust is low, sometimes defect to exploit or test boundaries
        if rate_total < 0.55:
            if rng.random() < 0.25:
                return 'D'
        return 'C'
